function calculateShipping(weightKg: number, zone: 'domestic' | 'international', isExpress: boolean): number {
  if (weightKg <= 0) throw new Error('Weight must be positive');
  const base = zone === 'domestic' ? 5 : 25;
  const perKg = zone === 'domestic' ? 1.5 : 8;
  const expr = isExpress ? 10 : 0;
  return base + weightKg * perKg + expr;
}
